sysauto_script.script:
(function executeRule() {
    var gr = new GlideRecord('x_vuram_financia_0_fcc_kyc_cases');
    gr.query();

    var startOfToday = new GlideDateTime(gs.beginningOfToday());
    var endOfToday = new GlideDateTime(gs.endOfToday());

    while (gr.next()) {
        var risk = (gr.getValue('risk_level') || '').toLowerCase();
        if (risk !== 'high' && risk !== 'medium' && risk !== 'low') continue;

        var kycExpiry = gr.getValue('kyc_expiry');
        if (!kycExpiry) continue;

        var reviewDate = new GlideDateTime(kycExpiry);

        // Add interval based on risk
        if (risk === 'high') {
            reviewDate.addYearsUTC(1);
        } else if (risk === 'medium') {
            reviewDate.addYearsUTC(3);
        } else {
            reviewDate.addYearsUTC(5);
        }

        // Notify 10 days before review date
        var notifyDate = new GlideDateTime(reviewDate);
        notifyDate.addDaysUTC(-10);

        // Fire only if today == notifyDate
        if (notifyDate.compareTo(startOfToday) >= 0 && notifyDate.compareTo(endOfToday) <= 0) {
            gs.eventQueue('kyc.review.due.soon.email', gr, '', '');
            gs.eventQueue('kyc.review.due.soon.bell', gr, '', '');
        }
    }
})();
